    // Convert input polygons to CGAL polygons
    typedef CGAL::Exact_predicates_exact_constructions_kernel Kernel;
    typedef Kernel::Point_2 Point_2;
    typedef CGAL::Polygon_2<Kernel> Polygon_2;
    typedef CGAL::Polygon_with_holes_2<Kernel> Polygon_with_holes_2;
    typedef std::list<Polygon_with_holes_2> Pwh_list_2;

    Polygon_2 cgal_poly1, cgal_poly2;
    for (const auto& p : P1.vectorPoints()) {
        cgal_poly1.push_back(Point_2(p.x(), p.y()));
    }
    for (const auto& p : P2.vectorPoints()) {
        cgal_poly2.push_back(Point_2(p.x(), p.y()));
    }

    // Compute difference using CGAL
    Pwh_list_2 difference_list;
    CGAL::difference(cgal_poly1, cgal_poly2, std::back_inserter(difference_list));

    // Convert result to PolygonWithHoles2d
    std::vector<PolygonWithHoles2d> result;
    for (const auto& pwh : difference_list) {
        PolygonWithHoles2d poly_with_holes;
