            ss2 << std::setprecision(std::numeric_limits<double>::digits10+1) << p.y();
            ss2 >> y;
            poly_with_holes.outer_boundary.push_back(Point2d(x, y));
        }
        // Holes
        for (const auto& hole : pwh.holes()) {
            std::vector<Point2d> hole_poly;
            for (const auto& p : hole) {
                double x, y;
                std::stringstream ss1, ss2;
                ss1 << std::setprecision(std::numeric_limits<double>::digits10+1) << p.x();
                ss1 >> x;
                ss2 << std::setprecision(std::numeric_limits<double>::digits10+1) << p.y();
                ss2 >> y;
                hole_poly.push_back(Point2d(x, y));
